/**
 * Whaleal 产品路线图组件
 */
import React from 'react';
import { Link } from 'gatsby';
import {
  BRAND_TAGLINE,
  PRODUCT_ROADMAP,
  BRAND_PRINCIPLES,
} from '../../constants/productRoadmap';
import { SHOPIFY_APP_STORE_URL, SHOPIFY_APP_STORE_LABEL, SHOPIFY_INSTALL_PAGE_PATH } from '../../constants/brand';
import './product-roadmap.css';

const STATUS_LABEL = {
  live: 'Live on App Store',
  coming: 'Coming Soon',
  planned: 'Planned',
  vision: '5-Year Vision',
};

export function ProductRoadmapCards({ showPrinciples = false, compact = false }) {
  return (
    <div className={`product-roadmap ${compact ? 'product-roadmap-compact' : ''}`}>
      {!compact && (
        <div className="product-roadmap-intro">
          <span className="product-roadmap-eyebrow">Whaleal Product Suite</span>
          <h2>Built for Shopify — Designed for 5 Years of Growth</h2>
          <p>{BRAND_TAGLINE}</p>
        </div>
      )}

      <div className="product-roadmap-timeline">
        {PRODUCT_ROADMAP.map((product, index) => (
          <div
            key={product.id}
            className={`product-roadmap-card product-roadmap-card--${product.status}`}
          >
            <div className="product-roadmap-card-header">
              <span className={`product-roadmap-status product-roadmap-status--${product.status}`}>
                {STATUS_LABEL[product.status]}
              </span>
              <span className="product-roadmap-year">{product.timeline}</span>
            </div>
            <h3>{product.name}</h3>
            <p className="product-roadmap-subtitle">{product.subtitle}</p>
            <p className="product-roadmap-desc">{product.description}</p>
            {product.status === 'live' && (
              <div className="product-roadmap-actions">
                {product.href && (
                  <Link to={product.href} className="product-roadmap-link">
                    {product.cta} →
                  </Link>
                )}
                <Link
                  to={SHOPIFY_INSTALL_PAGE_PATH}
                  className="product-roadmap-link product-roadmap-link-muted"
                >
                  Install on Shopify →
                </Link>
                <a
                  href={SHOPIFY_APP_STORE_URL}
                  className="product-roadmap-link product-roadmap-link-muted"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {SHOPIFY_APP_STORE_LABEL} →
                </a>
              </div>
            )}
            {index < PRODUCT_ROADMAP.length - 1 && (
              <div className="product-roadmap-connector" aria-hidden="true" />
            )}
          </div>
        ))}
      </div>

      {showPrinciples && (
        <div className="product-roadmap-principles">
          <h3>Brand Principles</h3>
          <div className="product-roadmap-principles-grid">
            {BRAND_PRINCIPLES.map((item) => (
              <div key={item.title} className="product-roadmap-principle">
                <strong>{item.title}</strong>
                <span>{item.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default ProductRoadmapCards;
